function ComparePanel(props:PanelProps){const [left,setLeft]=useState(props.initialComparisonRecordId??'');const [calibrationId,setCalibrationId]=useState('');const [excluded,setExcluded]=useState<number[]>([]);const [right,setRight]=useState('');const [ls,setLs]=useState('');const [rs,setRs]=useState('');const [sequence,setSequence]=useState('x');const [rabi,setRabi]=useState(1e7);const [t1,setT1]=useState(50000);const [t2,setT2]=useState(30000);const [comparison,setComparison]=useState<ScienceResult>();const [busy,setBusy]=useState(false);const [error,setError]=useState('');const calc=useCalculation(props,'simulation');const comparisonVersion=useRef(0);useEffect(()=>()=>{comparisonVersion.current++;},[]);const clearComparison=()=>{setExcluded([]);comparisonVersion.current++;setComparison(undefined);setError('');};const l=props.records.find(r=>r.id===left&&r.summary!==true),r=props.records.find(r=>r.id===right&&r.summary!==true);const input=()=>l?{...modelInputFromRecord(l,{}),readoutCalibrationRecordId:calibrationId||undefined,sourceSeriesId:ls||(l.result?.sourceSeries??l.result?.series)?.[0]?.id,modelParameters:comparisonModelParameters(l,{sequence,rabiHz:rabi,t1Ns:t1,t2Ns:t2,detuningHz:0,initialState:sequence==='t1'?'1':sequence==='x'?'0':'+x'})}:{};
 const compare=async(mask:number[]=excluded)=>{if(!l||!r)return;const current=++comparisonVersion.current;setBusy(true);setError('');try{const answer=await createScienceGateway(props.gateway).compare(l.id,r.id,ls||(l.result?.sourceSeries??l.result?.series)?.[0]?.id||'',rs||(r.result?.sourceSeries??r.result?.series)?.[0]?.id||'',mask);if(current===comparisonVersion.current){setComparison(answer);setExcluded(mask);}}catch(e){if(current===comparisonVersion.current){setComparison(undefined);setError(errorText(e));}}finally{setBusy(false);}};
 return <article className="science-card"><h3>复用实验配置，逐点核对</h3><p>仿真从保存记录冻结目标、扫描点和输入。补充模型参数独立记录，重新计算不会覆盖原对照。</p><div className="science-form"><RecordSelect onLoad={props.loadRecord} records={props.records.filter(r=>r.kind==='measurement')} value={left} onChange={v=>{setLeft(v);setLs('');setCalibrationId('');clearComparison();calc.invalidate();}} label="原始采集记录"/><label className="science-field"><span>使用的原始曲线</span><select value={ls} onChange={e=>{setLs(e.target.value);setCalibrationId('');clearComparison();calc.invalidate();}}><option value="">首条曲线</option>{(l?.result?.sourceSeries??l?.result?.series)?.map(s=><option key={s.id} value={s.id}>{s.label} · {s.quantity} / {s.unit}</option>)}</select></label></div>
 <div className="science-form"><label className="science-field"><span>模型实验</span><select disabled={l?.dataKind==='real'} value={measuredModelSequence(l)??sequence} onChange={e=>{setSequence(e.target.value);calc.invalidate();}}>{[['x','Rabi / X 旋转'],['t1','T₁'],['ramsey','Ramsey'],['echo','Hahn echo'],['cpmg','CPMG']].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><NumberField label="Rabi 频率" unit="Hz · 人工设定" value={rabi} onChange={v=>{setRabi(v);calc.invalidate();}}/><NumberField label="T₁" unit="ns · 人工设定" min={0} value={t1} onChange={v=>{setT1(v);calc.invalidate();}}/><NumberField label="T₂" unit="ns · 人工设定" min={0} value={t2} onChange={v=>{setT2(v);calc.invalidate();}}/></div>
 <ReadoutCalibrationImport onLoad={props.loadRecord} gateway={props.gateway} source={l} seriesId={ls||(l?.result?.sourceSeries??l?.result?.series)?.[0]?.id||''} records={props.records} value={calibrationId} onChange={id=>{setCalibrationId(id);calc.invalidate();}} refresh={props.refresh}/><div className="science-actions"><button disabled={!l||calc.busy} onClick={()=>void calc.run(input())}>按原扫描点仿真</button><button disabled={!l||calc.busy} onClick={()=>void calc.run(input(),true)}>保存同配置仿真</button></div><PanelError value={calc.error}/><div className="science-two-columns"><div>{l&&<Plot series={resultPlots(l.result).filter((_,i)=>!ls||(l.result?.sourceSeries??l.result?.series)?.[i]?.id===ls)} label="原始观测量"/>}</div><div><Result result={calc.result}/></div></div>
 <h4>已有记录之间的逐点对照</h4><div className="science-form"><RecordSelect onLoad={props.loadRecord} records={props.records.filter(r=>r.id!==left&&['measurement','simulation'].includes(r.kind))} value={right} onChange={v=>{setRight(v);setRs('');clearComparison();}} label="第二条保存记录（模型或复测）"/><label className="science-field"><span>对照曲线</span><select value={rs} onChange={e=>{setRs(e.target.value);clearComparison();}}><option value="">首条曲线</option>{(r?.result?.sourceSeries??r?.result?.series)?.map(s=><option key={s.id} value={s.id}>{s.label} · {s.quantity} / {s.unit}</option>)}</select></label></div><div className="science-actions"><button disabled={!l||!r||busy} onClick={()=>void compare()}>{busy?'正在核对…':'检查条件并比较'}</button></div><PanelError value={error}/>{comparison&&<>{comparison.observationCalibration&&<p className="science-note">以外部标定有效为条件的读出响应差值；未经本平台独立验收。</p>}<Result result={comparison}/>{comparison.axes?.x&&<div className="science-table-wrap"><table><thead><tr><th>扫描点</th><th>左记录</th><th>右记录</th><th>左 − 右</th><th>比较范围</th></tr></thead><tbody>{comparison.axes.x.values.map((x:number,i:number)=><tr key={i}><td>{fmt(x)}</td><td>{excluded.includes(x)?`${fmt(comparison.view?.originalLeftValues?.[i])}（暂不比较）`:fmt(comparison.series?.[0]?.values[i])}</td><td>{fmt(comparison.series?.[1]?.values[i])}</td><td>{comparison.series?.[2]?.values[i]==null?'缺点':fmt(comparison.series?.[2]?.values[i])}</td><td>{(l?.result?.sourceSeries??l?.result?.series)?.some(s=>(s.x??l?.result?.axes?.x?.values??[]).includes(x))&&<button disabled={busy} onClick={()=>void compare(excluded.includes(x)?excluded.filter(v=>v!==x):[...excluded,x])}>{excluded.includes(x)?'恢复此点':'暂不比较此点'}</button>}</td></tr>)}</tbody></table></div>}</>}
 <Details value={l} title="实测记录及原始来源"/><Details value={r} title="模型或复测记录及原始来源"/><p className="science-note">概率与 I/Q 或 ADC 响应不可直接相减。缺失点保留空缺；横轴、物理量、单位或配置不匹配时显示原因。</p></article>;
}
interface StabilityRound {intervalAnchor?:{acquiredAt?:string}|null;number:number;state:string;workflowId:string;startedAt:string;finishedAt?:string;frequencyHz:number|null;referenceFrequencyHz?:number;driftHz:number|null;t1Seconds:number|null;frequencyAttemptId?:string;t1AttemptId?:string;error?:string}
interface StabilitySchedule {clockPolicy?:string;id:string;revision:number;name?:string;sourceWorkflowId:string;resourceId:string;chipVersionId?:string;deploymentVersionId?:string;state:string;intervalSeconds:number;maxRounds:number;spanHz:number;points:number;nextDueAt?:string;createdAt:string;rounds:StabilityRound[]}
function StabilityPanel(props:PanelProps){const [schedules,setSchedules]=useState<StabilitySchedule[]>([]);const [selected,setSelected]=useState('');const [version,setVersion]=useState('');const [hours,setHours]=useState(3);const [rounds,setRounds]=useState(3);const [span,setSpan]=useState(2e6);const [points,setPoints]=useState(101);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
 const requestLock=useRef(false);
 let parameterError='';try{stabilityScheduleParameters({hours,rounds,span,points});}catch(cause){parameterError=errorText(cause);}
 useEffect(()=>{let active=true;let pending=false;const refresh=async()=>{if(pending)return;pending=true;try{const result=await props.gateway.get<{schedules:StabilitySchedule[]}>('/stability');if(active){setSchedules(result.schedules??[]);setError('');}}catch(e){if(active)setError(errorText(e));}finally{pending=false;}};void refresh();const timer=setInterval(()=>void refresh(),5000);return()=>{active=false;clearInterval(timer);};},[props.gateway]);
 const act=async(action?:string)=>{if(requestLock.current)return;requestLock.current=true;setBusy(true);setError('');try{const current=schedules.find(s=>s.id===selected);if(action&&!current)throw new Error('请先选择周期计划');if(!action&&!props.workflow)throw new Error('请先选择来源标定任务');const value=action&&current?await props.gateway.write<StabilitySchedule>(`/stability/schedules/${encodeURIComponent(current.id)}/actions`,{operationId:crypto.randomUUID(),expectedRevision:current.revision,action}):await props.gateway.write<StabilitySchedule>('/stability/schedules',{operationId:crypto.randomUUID(),sourceWorkflowId:props.workflow!.id,resourceId:props.workflow!.resourceIds?.[0]??props.workflow!.target,...stabilityScheduleParameters({hours,rounds,span,points})});setSchedules(old=>[...old.filter(s=>s.id!==value.id),value]);setSelected(value.id);props.notify(action?'周期计划状态已更新':'周期计划已保存，尚未启动');}catch(e){setError(errorText(e));}finally{requestLock.current=false;setBusy(false);}};
 const filtered=schedules.filter(s=>(!props.workflow||s.resourceId===(props.workflow.resourceIds?.[0]??props.workflow.target))&&(!version||s.chipVersionId===version));const schedule=filtered.find(s=>s.id===selected);const data=schedule?.rounds??[];const times=data.map(r=>{const at=stabilityRoundClock(schedule!,r).at;return at?new Date(at).getTime()/3600000:NaN;});const origin=Math.min(...times.filter(Number.isFinite));const x=times.map(t=>Number.isFinite(t)&&Number.isFinite(origin)?t-origin:NaN);const status=(s:string)=>({draft:'未启动',running:'运行中',paused:'已暂停',completed:'已完成',aborted:'已终止',queued:'等待执行',failed:'失败',interrupted:'采集中断'} as Record<string,string>)[s]??s;
 return <article className="science-card"><h3>周期定频 → 同轮 T₁</h3><StabilityReportPanel key={props.workflow?.id??"all"} gateway={props.gateway} resourceId={props.workflow?.resourceIds?.[0]??props.workflow?.target}/><p>本轮可信频率传给本轮 T₁；定频失败时保留缺测。{stabilityClockNote(schedule)}重启后计划暂停，需明确恢复。</p><div className="science-form"><NumberField label="轮次间隔" unit="小时" min={stabilityScheduleBounds.hours.min} max={stabilityScheduleBounds.hours.max} step={1/60} value={hours} onChange={setHours}/><NumberField label="最大轮次" min={1} max={1000} step={1} value={rounds} onChange={setRounds}/><NumberField label="精扫频宽" unit="Hz" min={1000} max={1e8} value={span} onChange={setSpan}/><NumberField label="频率点数" min={3} max={161} step={1} value={points} onChange={setPoints}/></div><div className="science-actions"><button disabled={!props.workflow||busy||Boolean(parameterError)} onClick={()=>void act()}>保存周期计划</button><small>源任务：{props.workflow?.name??'尚未选择'}</small></div>{parameterError&&<p role="status" className="science-note">{parameterError}</p>}<PanelError value={error}/>
 <div className="science-form"><label className="science-field"><span>芯片版本</span><select aria-label="计划芯片版本" value={version} onChange={e=>{setVersion(e.target.value);setSelected('');}}><option value="">全部版本</option>{[...new Set(schedules.map(s=>s.chipVersionId).filter(Boolean))].map(v=><option key={v} value={v}>{v}</option>)}</select></label><label className="science-field"><span>已有周期计划</span><select aria-label="已有周期计划" value={selected} onChange={e=>setSelected(e.target.value)}><option value="">选择计划查看趋势</option>{filtered.map(s=><option key={s.id} value={s.id}>{s.name??s.id} · {status(s.state)} · {s.resourceId}</option>)}</select></label></div>
 {schedule?<><div className="science-actions">{['draft','paused'].includes(schedule.state)&&<button disabled={busy} className="science-primary" onClick={()=>void act('start')}>启动周期测量</button>}{schedule.state==='running'&&<button disabled={busy} onClick={()=>void act('pause')}>暂停后续轮次</button>}{['draft','running','paused'].includes(schedule.state)&&<button disabled={busy} onClick={()=>void act('abort')}>终止周期计划</button>}<span>{status(schedule.state)} · 下轮 {schedule.nextDueAt?new Date(schedule.nextDueAt).toLocaleString():schedule.state==='running'?'待首测采集完成':'未安排'}</span></div><div className="science-two-columns"><Plot label="频率漂移" series={[{name:'相对本轮参考频率',x,y:data.map(r=>r.driftHz),xUnit:'距首轮 / h',yUnit:'Hz',source:'measured'}]}/><Plot label="本轮 T₁ 趋势" series={[{name:'T₁',x,y:data.map(r=>finite(r.t1Seconds)?r.t1Seconds*1e6:null),xUnit:'距首轮 / h',yUnit:'μs',source:'measured'}]}/></div><div className="science-table-wrap"><table><thead><tr><th>轮次 / 时间基准</th><th>状态</th><th>频率 / Hz</th><th>漂移 / Hz</th><th>T₁ / μs</th><th>来源 / 原因</th></tr></thead><tbody>{data.map(r=><tr key={r.number}><td>{r.number}<small>{stabilityRoundClock(schedule,r).label}：{stabilityRoundClock(schedule,r).at?new Date(stabilityRoundClock(schedule,r).at!).toLocaleString():'尚无采集时间'}</small></td><td>{status(r.state)}</td><td>{r.frequencyHz==null?'未获得有效频率':fmt(r.frequencyHz)}</td><td>{fmt(r.driftHz)}</td><td>{r.t1Seconds==null?'本轮未测':fmt(r.t1Seconds*1e6)}</td><td>{r.error??r.workflowId}<Details value={{frequencyAttemptId:r.frequencyAttemptId,t1AttemptId:r.t1AttemptId,referenceFrequencyHz:r.referenceFrequencyHz,queuedAt:r.startedAt,intervalAnchor:r.intervalAnchor,finishedAt:r.finishedAt}} title="关联证据"/></td></tr>)}</tbody></table></div><Details value={schedule} title="完整计划与轮次记录"/></>:<Empty>选择已有计划查看频率与 T₁；没有记录的时段保持空缺。</Empty>}</article>;
}
function IndependentHalfGate({scan,record}:{scan?:ScienceRecord;record:ScienceRecord}){
 const evidence=sameHalfGateEvidence(scan,record);if(!evidence.ready)return <><Empty>门保真度待确认：{evidence.reason}</Empty><Details value={record} title="该记录的原始诊断与方法"/></>;
 const gate=evidence.gate,irb=gate.irb,pulse=evidence.pulse.identity,interval=irb?.bootstrap?.intervals_unclipped?.F_X_half_conditional;
 return <><p className="science-pill">{evidence.reason}</p><Result result={record.result}/><div className="science-metrics"><div><small>同一 X/2 门条件保真度</small><strong>{fmt(irb?.F_X_half_conditional)}</strong><small>95% 配对 bootstrap 条件区间：{interval?.map(fmt).join(' – ')??'未记录'}</small></div><div><small>实际目标脉冲</small><strong>{pulse?.shape} · {fmt(pulse?.durationS*1e9)} ns</strong><small>半门幅度 {fmt(pulse?.amplitude)} · {scienceGateCoefficientLabel(pulse)}</small></div><div><small>独立参考</small><strong>PRE 留出 {gate.reference?.pre?.projection?.validation_captures?.length??'—'} 轮</strong><small>POST 漂移诊断上界 {fmt(gate.reference?.post?.reference_drift_upper_diagnostic)}</small></div></div><p className="science-note">区间以本次独立 IQ 投影、采集、脉冲实现及单指数模型为条件，不包含系统模型误差，也不是泄漏估计。</p>{(!gate.rabiLineage?.amplitude||!gate.rabiLineage?.time)&&<p className="science-note">幅度 / 时间 Rabi 来源尚未全部闭合，R11 整体验收仍待补齐；本次同门表征单独保留。</p>}{gate.rabiLineage?.timeWindow&&<p className="science-note">时间窗来源：DC 时间 Rabi 连续拟合 {fmt(gate.rabiLineage.timeWindow.sourceContinuousDurationS*1e9)} ns → 0.25 ns 网格 {fmt(gate.rabiLineage.timeWindow.targetDurationS*1e9)} ns，量化偏差 {fmt(gate.rabiLineage.timeWindow.quantizationErrorS*1e12)} ps。它只支持工作点/时间窗；形状 π 与半门采集分别证明实际旋转。</p>}<Details value={{pulse:evidence.pulse,rabiLineage:gate.rabiLineage,sourceReferences:gate.sourceReferences,bootstrap:irb?.bootstrap,reference:gate.reference}} title="脉冲、扫描与门表征的独立来源"/></>;
}
function DragPanel(props:PanelProps){const [input,setInput]=useState<ScienceInput>({amplitude:.5,durationNs:20,frequencyHz:5e9,phaseDeg:0,shape:'gaussian',sigmaNs:20/6,points:201,alphaNs:0});const [rabiId,setRabiId]=useState('');const [scanId,setScanId]=useState('');const [rbId,setRbId]=useState('');const calc=useCalculation(props,'drag');const update=(k:string,v:any)=>{setInput({...input,[k]:v});calc.invalidate();};const rabi=props.records.find(r=>r.id===rabiId&&r.summary!==true),scan=props.records.find(r=>r.id===scanId&&r.summary!==true),rb=props.records.find(r=>r.id===rbId&&r.summary!==true);const payload=()=>({...input,rabiSourceRecordId:rabiId||undefined,coefficientScanRecordId:scanId||undefined,independentRBRecordId:rbId||undefined});const importRabi=()=>{if(!rabi)return;const p={...rabi.result?.parameters,...rabi.input};setInput({...input,amplitude:Number(p.drive_amp??p.amplitude??input.amplitude),durationNs:Number(p.drive_length_s!=null?p.drive_length_s*1e9:p.durationNs??input.durationNs),frequencyHz:Number(p.drive_hz??p.frequencyHz??input.frequencyHz)});calc.invalidate();};
 return <article className="science-card"><h3>XY 驱动 DRAG 与独立门验证</h3><p>零参考相位下 I 为主包络，Q = −α · dI/dt。这里的 I/Q 是驱动基带样点，读出 I/Q 另列在来源记录。</p><div className="science-form"><RecordSelect onLoad={props.loadRecord} records={props.records} value={rabiId} onChange={v=>{setRabiId(v);calc.invalidate();}} label="Rabi 标定来源"/><button disabled={!rabi} onClick={importRabi}>带入幅度与脉宽</button><NumberField label="驱动幅度" unit="a.u." value={input.amplitude} onChange={v=>update('amplitude',v)}/><NumberField label="脉宽" unit="ns" min={0} value={input.durationNs} onChange={v=>update('durationNs',v)}/><NumberField label="高斯 σ" unit="ns" min={0} value={input.sigmaNs} onChange={v=>update('sigmaNs',v)}/><NumberField label="DRAG α" unit="ns" value={input.alphaNs} onChange={v=>update('alphaNs',v)}/><NumberField label="初相" unit="°" value={input.phaseDeg} onChange={v=>update('phaseDeg',v)}/></div><Actions busy={calc.busy} onPreview={()=>void calc.run(payload())} onSave={()=>void calc.run(payload(),true)}/><PanelError value={calc.error}/><Result result={calc.result}/><div className="science-two-columns"><div><RecordSelect onLoad={props.loadRecord} records={props.records} value={scanId} onChange={v=>{setScanId(v);calc.invalidate();}} label="系数扫描 / 候选复测记录"/>{scan?<><Result result={scan.result}/><ScienceAcquisitionEvidence key={scan.id} record={scan} gateway={props.gateway} renderResult={result=><Result result={result}/>} Plot={Plot}/></>:<Empty>尚未关联 DRAG 系数扫描和候选复测</Empty>}</div><div><RecordSelect onLoad={props.loadRecord} records={props.records.filter(r=>r.result?.procedureId==='sq_drag_irb'||r.provenance?.procedureId==='sq_drag_irb')} value={rbId} onChange={v=>{setRbId(v);calc.invalidate();}} label="独立门表征记录（参考与交错 RB）"/>{rb?<><IndependentHalfGate scan={scan} record={rb}/><ScienceAcquisitionEvidence key={rb.id} record={rb} gateway={props.gateway} renderResult={result=><Result result={result}/>} Plot={Plot}/></>:<Empty>门保真度待测。DRAG 波形或系数扫描不能作为门保真度。</Empty>}</div></div><p className="science-note">泄漏改善需有可分辨 |2⟩ 布居的测量；本页不从模型波形推断实测保真度。</p></article>;
}
function ShelvePanel(props:PanelProps){const [actualId,setActualId]=useState('');const actualRecords=props.records.filter(r=>r.kind==='measurement'&&(r.result?.procedureId??r.provenance?.procedureId)==='sq_shelve_readout_compare');const actual=actualRecords.find(r=>r.id===actualId&&r.summary!==true);const [f01,setF01]=useState(5e9);const [nu,setNu]=useState(4.875e9);const [drive,setDrive]=useState(4.75e9);const [off,setOff]=useState([[0,0],[0,0]]);const [on,setOn]=useState([[0,0],[0,0]]);const [specId,setSpecId]=useState('');const [piId,setPiId]=useState('');const calc=useCalculation(props,'shelve');const f12=2*nu-f01;const input=()=>({f01Hz:f01,twoPhotonFrequencyHz:nu,anharmonicityHz:f12-f01,driveFrequencyHz:drive,counts:off,shelvedCounts:on,spectroscopyRecordId:specId||undefined,pi12CalibrationRecordId:piId||undefined});const countsEditor=(name:string,counts:number[][],set:(v:number[][])=>void)=><div><h4>{name}</h4><div className="science-counts">{counts.flatMap((row,i)=>row.map((v,j)=><NumberField key={`${i}${j}`} label={`制备 |${i}⟩ → 判为 ${j}`} unit="次" value={v} min={0} step={1} onChange={n=>{set(counts.map((r,a)=>r.map((cell,b)=>a===i&&b===j?n:cell)));calc.invalidate();}}/>))}</div></div>;
 return <article className="science-card"><h3>SHELVE 辅助读出</h3><RecordSelect onLoad={props.loadRecord} records={actualRecords} value={actualId} onChange={setActualId} label="真实 SHELVE 留出读出记录"/>{actual?<><Result result={actual.result}/><Details value={actual} title="该次真实采集的冻结输入与来源"/></>:<p>关联运行证据后，可在此查看首测与独立复测的实际分类计数；手工计数不会成为真实采集记录。</p>}<h4>候选估算与手工计数</h4><p>先确认副峰是 0→2 双光子激发，再用制备 |1⟩ 的独立谱核准 f₁₂，最后标定 π₁₂。</p><div className="science-form"><NumberField label="0→1 主峰 f₀₁" unit="Hz" min={0} value={f01} onChange={v=>{setF01(v);calc.invalidate();}}/><NumberField label="双光子候选驱动 ν" unit="Hz" min={0} value={nu} onChange={v=>{setNu(v);calc.invalidate();}}/><NumberField label="拟用 1→2 驱动频率" unit="Hz" min={0} value={drive} onChange={v=>{setDrive(v);calc.invalidate();}}/></div><div className="science-metrics"><div><small>f₁₂ ≈ 2ν − f₀₁ / Hz</small><strong>{fmt(f12)}</strong></div><div><small>非谐性 α = f₁₂ − f₀₁ / Hz</small><strong>{fmt(f12-f01)}</strong></div><div><small>驱动失谐 δ / Hz</small><strong>{fmt(drive-f12)}</strong></div></div><span className="science-pill">候选估算 · 待独立标定</span><div className="science-form"><RecordSelect onLoad={props.loadRecord} records={props.records} value={specId} onChange={v=>{setSpecId(v);calc.invalidate();}} label="独立 1→2 共振记录"/><RecordSelect onLoad={props.loadRecord} records={props.records} value={piId} onChange={v=>{setPiId(v);calc.invalidate();}} label="π₁₂ 标定记录"/></div>
 <h4>验证样本按搁置前逻辑态计数</h4><p>输入已有验证样本计数。手工填入的数字标为输入数据计算；真实验证结论需关联原始采集记录。</p><div className="science-two-columns">{countsEditor('关闭 SHELVE',off,setOff)}{countsEditor('启用 SHELVE',on,setOn)}</div><p>e₀ = n₀₁ / (n₀₀+n₀₁)，e₁ = n₁₀ / (n₁₀+n₁₁)，F = 1 − (e₀+e₁)/2。两种初态等权；改善用百分点报告。</p><Actions busy={calc.busy} onPreview={()=>void calc.run(input())} onSave={()=>void calc.run(input(),true)}/><PanelError value={calc.error}/>{calc.result?.metrics&&<div className="science-metrics">{[['withoutShelve','关闭 SHELVE'],['withShelve','启用 SHELVE']].map(([key,label])=>{const m=calc.result!.metrics![key] as ScienceInput|undefined;return m&&<div key={key}><small>{label} · 输入计数计算</small><strong>F = {fmt(m.fidelity*100)}%</strong><span>e₀ = {fmt(m.error0*100)}% · e₁ = {fmt(m.error1*100)}%</span><small>样本 |0⟩ / |1⟩：{m.samples?.join(' / ')}；标准误 {fmt(m.standardError*100)} 个百分点</small></div>;})}<div><small>启用 − 关闭</small><strong>{finite(calc.result.metrics.fidelityGain)?fmt(calc.result.metrics.fidelityGain*100):'未计算'} 个百分点</strong><small>是否改善仍需独立实测验证</small></div></div>}<Result result={calc.result}/>{[specId,piId].filter(Boolean).map(id=><Details key={id} value={props.records.find(r=>r.id===id&&r.summary!==true)} title={id===specId?'查看共振核准来源':'查看 π₁₂ 标定来源'}/>)}</article>;
}
function FluxPanel(props:PanelProps){const [id,setId]=useState('');const [biasIndex,setBiasIndex]=useState(0);const [freqIndex,setFreqIndex]=useState(0);const [purpose,setPurpose]=useState('work');const [channel,setChannel]=useState('');const [wp,setWp]=useState('');const [draft,setDraft]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const calc=useCalculation(props,'flux');const record=props.records.find(r=>r.id===id&&r.summary!==true);const nativeFlux=record?.result?.procedureId==='ro_flux_scan'?record.result.scienceFlux:undefined;const input=record?.input??{};const source=(record?.result?.grid??record?.result?.heatmap??input) as ScienceInput;
 const rawBias=source.biasValues??source.y??input.biasValues;const rawFreq=source.frequencyHz??source.x??input.frequencyHz;const rawMatrix=source.amplitude??source.values??input.amplitude;const biases:number[]=Array.isArray(rawBias)&&rawBias.every(finite)?rawBias:[];const frequencies:number[]=Array.isArray(rawFreq)&&rawFreq.every(finite)?rawFreq:[];const matrix:(number|null)[][]=Array.isArray(rawMatrix)&&rawMatrix.every(row=>Array.isArray(row)&&row.every(v=>v===null||finite(v)))?rawMatrix:[];const validGrid=biases.length>0&&frequencies.length>0&&matrix.length===biases.length&&matrix.every(row=>row.length===frequencies.length)&&biases.length*frequencies.length<=100000;const bi=Math.min(biasIndex,Math.max(0,biases.length-1)),fi=Math.min(freqIndex,Math.max(0,frequencies.length-1));const values=matrix.flat().filter(finite);const lo=values.reduce((a,v)=>Math.min(a,v),Infinity),hi=values.reduce((a,v)=>Math.max(a,v),-Infinity);const biasUnit=source.biasUnit??source.yUnit??input.biasUnit??'未记录';const signalUnit=source.signalUnit??source.unit??input.signalUnit??'未记录';const point=props.records.find(r=>r.id===wp&&r.summary!==true);
 const savePoint=async()=>{if(!record||!validGrid)return;setBusy(true);setError('');try{const selectedCut=nativeFlux?.points?.filter((p:any)=>p.phase==='cavity')[bi];if(nativeFlux&&selectedCut?.analysis?.accepted!==true)throw new Error('所选原生截线未通过诊断，不能保存为可执行点位');if(!nativeFlux&&!channel.trim())throw new Error('请填写原扫描使用的磁通控制通道');const result=await createScienceGateway(props.gateway).save('working_point',{sourceRecordId:record.id,purpose,fluxChannel:nativeFlux?nativeFlux.route.lineId:channel.trim(),bias:biases[bi],biasUnit,readoutFrequencyHz:nativeFlux?selectedCut.readoutFrequencyHz:frequencies[fi],selectedBiasIndex:bi,selectedFrequencyIndex:fi},record.scope,record.reference&&!nativeFlux?{reference:record.reference}:{});await props.refresh();setWp(result.id);props.notify('点位已保存');}catch(e){setError(errorText(e));}finally{setBusy(false);}};
 const loadData=async(save=false)=>{setError('');try{const data=JSON.parse(draft);const result=await calc.run({...data,selectedBiasIndex:bi,purpose},save);if(save&&result&&'id' in result){setId(result.id);setBiasIndex(0);setFreqIndex(0);}}catch(e){setError(`输入数据格式错误：${errorText(e)}`);}};
 return <article className="science-card"><h3>磁通扫描与可复查的工作点</h3><p>原生扫描显示读取腔原始 IQ 响应，未经归一化时不称为 S₂₁；点击色块查看对应偏置的原始截线。腔共振与比特 0→1 频率分别保存。</p><RecordSelect onLoad={props.loadRecord} records={props.records.filter(r=>r.kind==='flux'||r.kind==='measurement')} value={id} onChange={v=>{setId(v);setBiasIndex(0);setFreqIndex(0);setWp('');setError('');}} label="原始磁通扫描记录"/>
 {validGrid?<><div className="science-two-columns"><figure className="science-plot"><figcaption>{nativeFlux?'原始读取腔 IQ 幅值':'输入响应'} / {signalUnit} · {sourceLabel(record?.result?.source??record?.result?.dataKind)}</figcaption><svg viewBox="0 0 650 390" role="img" aria-label="S21磁通二维谱"><text x="14" y="22">探测频率 / {plotAxis(frequencies[0],frequencies[frequencies.length-1],'Hz').unit}</text>{biases.flatMap((bias,b)=>frequencies.map((frequency,f)=>{const value=matrix[b]?.[f];return <rect key={`${b}-${f}`} x={78+b/biases.length*540} y={38+(frequencies.length-f-1)/frequencies.length*290} width={540/biases.length+.25} height={290/frequencies.length+.25} fill={finite(value)?`hsl(${245-205*(value-lo)/(hi-lo||1)} 68% 52%)`:'transparent'} stroke={b===bi&&f===fi?'currentColor':'none'} strokeWidth={2} onClick={()=>{setBiasIndex(b);setFreqIndex(f);}}><title>{bias} {biasUnit} · {frequency} Hz · {fmt(value)} {signalUnit}</title></rect>;}))}{discreteAxisIndices(frequencies.length).map(i=><text key={"f"+i} x="69" y={42+(frequencies.length-i-.5)/frequencies.length*290} textAnchor="end">{plotAxis(frequencies[0],frequencies[frequencies.length-1],"Hz").format(frequencies[i])}</text>)}{discreteAxisIndices(biases.length).map(i=><text key={"b"+i} x={78+(i+.5)/biases.length*540} y="352" textAnchor="middle">{fmt(biases[i])}</text>)}<text x="350" y="380" textAnchor="middle">{nativeFlux?'偏置设定电压':'输入偏置'} / {biasUnit}</text></svg><div className="science-legend"><span>色阶 {fmt(lo)} → {fmt(hi)} {signalUnit}</span><span>空白：缺测</span></div></figure><Plot label={`原始截线 · 偏置 ${fmt(biases[bi])} ${biasUnit}`} series={[{name:nativeFlux?'原始读取腔 IQ 样点':'输入响应样点',x:frequencies,y:matrix[bi]??[],xUnit:'Hz',yUnit:signalUnit,source:record?.result?.source}]} cursor={fi} onPoint={setFreqIndex}/></div><label className="science-slider">选择偏置截线<input type="range" aria-label="磁通截线" min={0} max={biases.length-1} value={bi} step={1} onChange={e=>setBiasIndex(Number(e.target.value))}/></label><div className="science-metrics"><div><small>偏置 / {biasUnit}</small><strong>{fmt(biases[bi])}</strong></div><div><small>选中探测频率 / Hz</small><strong>{fmt(frequencies[fi])}</strong></div><div><small>{nativeFlux?'原始读取腔 IQ':'输入响应'} / {signalUnit}</small><strong>{fmt(matrix[bi]?.[fi])}</strong></div><div><small>独立比特频率</small><strong>待同偏置定频</strong></div></div><p className="science-note">原生点位保存独立复测得到的腔频候选，并保留偏置设定值及其证据。设定电压策略未独立测压；离线输入点只用于查看。复杂谱线仍需复测，不从腔谱推导比特跃迁。新建采集请进入“手动测量 → 新建实验 → 偏置扫描 / 工作点核查”。</p><div className="science-form"><label className="science-field"><span>点位用途</span><select value={purpose} onChange={e=>setPurpose(e.target.value)}><option value="work">工作点</option><option value="idle">闲置点</option></select></label><label className="science-field"><span>原扫描磁通通道</span><input placeholder="例如 Z_Q11" value={nativeFlux?nativeFlux.route.lineId:channel} readOnly={!!nativeFlux} onChange={e=>setChannel(e.target.value)}/></label><button onClick={()=>{const row=matrix[bi];const valid=row.map((v,i)=>({v,i})).filter((p):p is {v:number;i:number}=>finite(p.v));if(valid.length)setFreqIndex(valid.reduce((a,b)=>b.v<a.v?b:a).i);}}>选择本截线最低响应</button><button disabled={busy||!finite(matrix[bi]?.[fi])} onClick={()=>void savePoint()}>保存选中点位</button></div></>:<Empty>{record?'该记录没有可绘制的二维样点。原始谱线保留在来源详情中。':'先选择已有扫描记录；没有采集数据时不生成示例热图。'}</Empty>}
 <PanelError value={error||calc.error}/><h4>闲置点 / 工作点调用</h4><RecordSelect onLoad={props.loadRecord} records={props.records} kind="working_point" value={wp} onChange={setWp} label="已保存点位"/>{point&&<><div className="science-metrics"><div><small>用途</small><strong>{(point.result?.point??point.input).purpose==='idle'?'闲置点':'工作点'}</strong></div><div><small>{(point.result?.point??point.input).fluxChannel} / {(point.result?.point??point.input).biasUnit}</small><strong>{fmt((point.result?.point??point.input).bias)}</strong></div><div><small>读出频率 / Hz</small><strong>{fmt((point.result?.point??point.input).readoutFrequencyHz)}</strong></div><div><small>比特频率 / Hz</small><strong>{fmt((point.result?.point??point.input).driveFrequencyHz)}</strong></div></div><div className="science-actions"><button disabled={!props.onManual} className="science-primary" onClick={()=>{try{props.onManual?.(readWorkingPoint(point,props.workflow?.resourceIds?.[0]??props.workflow?.target));}catch(e){setError(errorText(e));}}}>在手动测量中打开</button><button onClick={()=>{setId((point.result?.point??point.input).sourceRecordId);setBiasIndex(point.result?.point?.selectedBiasIndex??point.input.selectedBiasIndex??0);setFreqIndex(point.result?.point?.selectedFrequencyIndex??point.input.selectedFrequencyIndex??0);}}>回看原始谱线</button></div>{point.result?.fluxPointEvidence?.schema==='qcal-flux-point-evidence/2'&&<p className="science-note">偏置为设定电压，未独立测压。调用时重新施加，结束后返回声明设置；不表示器件当前保持此偏置。</p>}<Details value={point} title="点位与版本来源"/></>}
 <details className="science-details"><summary>导入离线扫描数据进行计算</summary><p>对象字段：biasValues、biasUnit、frequencyHz、amplitude（偏置×频率矩阵）、signalUnit。导入数据仅标为输入数据，不成为真实采集证据。</p><textarea className="science-json-input" rows={7} value={draft} onChange={e=>{setDraft(e.target.value);calc.invalidate();}} placeholder={'{"biasValues":[],"biasUnit":"V","frequencyHz":[],"amplitude":[],"signalUnit":"dB"}'}/><Actions busy={calc.busy} onPreview={()=>void loadData()} onSave={()=>void loadData(true)}/><Result result={calc.result}/></details>{record&&<Details value={record} title="原始扫描与完整来源"/>}</article>;
}

